INSERT INTO `book_summaries` VALUES (1,1,'{\"intro\": \"《思考，快与慢》是诺贝尔经济学奖得主丹尼尔·卡尼曼的代表作，系统性地介绍了影响人类判断与决策的认知偏误。本书分为五个部分，深入探讨了大脑的两个系统——快速、直觉、情绪化的系统1，以及缓慢、理性、逻辑化的系统2之间的互动关系。\\n\\n卡尼曼通过丰富的实验案例和研究成果，揭示了人类思维中存在的系统性偏差。他指出，尽管系统1为我们提供了快速、自动的判断，但它也容易导致各种思维错误；而系统2虽然更加理性，却常常懒惰且容易疲劳。\\n\\n本书不仅是一部学术著作，更是一本实用的人生指南，帮助读者理解自己在生活、工作、投资等各个领域可能犯下的决策错误。\", \"highlights\": [\"深入理解大脑的两种思维模式\", \"识别和避免常见认知偏误\", \"提升判断质量和决策能力\", \"诺贝尔奖得主的毕生研究精华\"]}','2026-03-17 23:39:04','2026-04-02 19:49:09'),(2,2,'{\"intro\": \"     《影响力》是美国社会心理学家罗伯特·西奥迪尼的经典著作，被誉为说服心理学与行为经济学的必读书目。全书以大量实验与真实案例为基础，系统揭示驱动人们顺从行为的六大心理原则：互惠、承诺与一致、社会认同、喜好、权威、稀缺。作者用通俗笔触拆解商业营销、社交沟通、职场谈判中的隐性操控逻辑，解释人为何常不自觉被他人影响、做出非理性决策。该书兼具学术深度与实用价值，既帮读者识破套路、守住判断边界，也教会合理运用影响力原则，提升沟通说服力。\"}','2026-03-19 20:23:45','2026-05-27 22:44:14'),(3,3,'{\"intro\": \"讨论群体心理的形成、暗示与情绪传染，以及个体在群体中的行为变化。\"}','2026-03-19 20:23:45','2026-03-20 00:14:08');
/*!40000 ALTER TABLE `book_summaries` ENABLE KEYS */;
UNLOCK TABLES;

